import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class ChangeCalculatorEdgeCheck {
    private static int failures = 0;

    public static void main(String[] args) {
        check("change for 1 cent", new ChangeCalculator(Arrays.asList(1, 5, 10, 25)), 1, Arrays.asList(1));
        check("single coin", new ChangeCalculator(Arrays.asList(1, 5, 10, 25, 100)), 25, Arrays.asList(25));
        check("multiple coins", new ChangeCalculator(Arrays.asList(1, 5, 10, 25, 100)), 15, Arrays.asList(5, 10));
        check("lilliputian currency", new ChangeCalculator(Arrays.asList(1, 4, 15, 20, 50)), 23, Arrays.asList(4, 4, 15));
        check("lower elbonian currency", new ChangeCalculator(Arrays.asList(1, 5, 10, 21, 25)), 63, Arrays.asList(21, 21, 21));

        List<Integer> expected999 = new ArrayList<>(Arrays.asList(2, 2, 5, 20, 20, 50));
        expected999.addAll(Collections.nCopies(9, 100));
        check("large amount", new ChangeCalculator(Arrays.asList(1, 2, 5, 10, 20, 50, 100)), 999, expected999);

        check("possible without unit coin", new ChangeCalculator(Arrays.asList(2, 5, 10, 20, 50)), 21, Arrays.asList(2, 2, 2, 5, 10));
        check("another without unit coin", new ChangeCalculator(Arrays.asList(4, 5)), 27, Arrays.asList(4, 4, 4, 5, 5, 5));
        check("greedy is not optimal", new ChangeCalculator(Arrays.asList(1, 10, 11)), 20, Arrays.asList(10, 10));
        check("zero change", new ChangeCalculator(Arrays.asList(1, 5, 10, 21, 25)), 0, Collections.emptyList());

        ChangeCalculator smallCoins = new ChangeCalculator(Arrays.asList(5, 10));
        checkException("less than smallest coin", smallCoins, 3, "The total 3 cannot be represented in the given currency.");
        checkException("larger than all coins", smallCoins, 94, "The total 94 cannot be represented in the given currency.");
        checkException("negative change", new ChangeCalculator(Arrays.asList(1, 2, 5)), -5, "Negative totals are not allowed.");

        check("unsorted and duplicate coins", new ChangeCalculator(Arrays.asList(25, 1, 5, 1, 10)), 15, Arrays.asList(5, 10));

        if (failures != 0) {
            throw new AssertionError(failures + " edge case(s) failed");
        }
        System.out.println("All edge-case checks passed.");
    }

    private static void check(String name, ChangeCalculator calculator, int total, List<Integer> expected) {
        try {
            List<Integer> actual = calculator.computeMostEfficientChange(total);
            if (expected.equals(actual)) {
                pass(name);
            } else {
                fail(name + ": expected " + expected + " but got " + actual);
            }
        } catch (RuntimeException e) {
            fail(name + ": unexpected exception " + e);
        }
    }

    private static void checkException(String name, ChangeCalculator calculator, int total, String expectedMessage) {
        try {
            calculator.computeMostEfficientChange(total);
            fail(name + ": expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            if (expectedMessage.equals(e.getMessage())) {
                pass(name);
            } else {
                fail(name + ": expected message '" + expectedMessage + "' but got '" + e.getMessage() + "'");
            }
        } catch (RuntimeException e) {
            fail(name + ": expected IllegalArgumentException but got " + e);
        }
    }

    private static void pass(String name) {
        System.out.println("PASS: " + name);
    }

    private static void fail(String message) {
        failures++;
        System.out.println("FAIL: " + message);
    }
}
